1	/**
2	 * Webhook endpoint management and the bridge from `webhook.delivery_requested` to the delivery queue.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, wouldExceedLimit
5	 */
6	import { createHmac } from "node:crypto";
7	import { wouldExceedLimit } from "@/config/plan-limits";
8	import { subscribe } from "@/lib/event-bus";
9	import { isEnabled } from "@/lib/feature-flags";
10	import { randomToken } from "@/lib/hash";
11	import { assertCan } from "@/lib/permissions";
12	import { assertOrgScope } from "@/lib/tenant";
13	import * as orgRepo from "@/server/repositories/organization-repository";
14	import * as webhookRepo from "@/server/repositories/webhook-repository";
15	import { requireFound, webhookResource } from "./_support";
16	import type {
17	  CreateWebhookInput,
18	  DeleteWebhookInput,
19	  UpdateWebhookInput,
20	} from "@/schemas/webhook";
21	import type { WebhookEndpointRow } from "@/server/db/schema/webhooks";
22	import type { OrgId } from "@/types/common";
23	import type { Unsubscribe } from "@/types/event";
24	import type { FlagContext } from "@/types/feature-flag";
25	import type { Actor } from "@/types/member";
26	
27	/** Length in bytes of a generated endpoint signing secret. */
28	const SECRET_BYTES = 32;
29	
30	export async function listWebhooks(
31	  actor: Actor,
32	  orgId: OrgId,
33	): Promise<readonly WebhookEndpointRow[]> {
34	  assertOrgScope(actor, orgId);
35	  assertCan(actor, "webhook:manage", webhookResource(orgId, null));
36	  return webhookRepo.listEndpoints(orgId);
37	}
38	
39	/**
40	 * Creating an endpoint is gated twice: the `webhooks` flag has to be on for
41	 * the org's plan, and the plan's endpoint count must have room. A secret is
42	 * minted here and never regenerated — rotating it means deleting the endpoint.
43	 */
44	export async function createWebhook(
45	  actor: Actor,
46	  input: CreateWebhookInput,
47	): Promise<WebhookEndpointRow> {
48	  assertOrgScope(actor, input.orgId);
49	  assertCan(actor, "webhook:manage", webhookResource(input.orgId, null));
50	
51	  const org = requireFound(
52	    await orgRepo.findOrgById(input.orgId),
53	    "Organization",
54	    input.orgId,
55	  );
56	
57	  if (!isEnabled("webhooks", flagContextFor(actor, org.plan, org.settings.enabledFlagOverrides))) {
58	    throw new Error("Outgoing webhooks are not included in this plan");
59	  }
60	
61	  // Only live endpoints consume the allowance: a switched-off endpoint is
62	  // parked, receives nothing, and can be deleted or re-enabled later.
63	  const live = await webhookRepo.listEndpoints(input.orgId);
64	  const used = live.filter((endpoint) => endpoint.enabled).length;
65	  if (wouldExceedLimit(org.plan, "webhooks", used)) {
66	    throw new Error(`Plan ${org.plan} allows ${used} webhook endpoints`);
67	  }
68	
69	  return webhookRepo.insertEndpoint(input, randomToken(SECRET_BYTES));
70	}
71	
72	export async function updateWebhook(
73	  actor: Actor,
74	  input: UpdateWebhookInput,
75	): Promise<WebhookEndpointRow> {
76	  assertOrgScope(actor, input.orgId);
77	  assertCan(actor, "webhook:manage", webhookResource(input.orgId, input.webhookId));
78	  return webhookRepo.updateEndpoint(input);
79	}
80	
81	export async function deleteWebhook(
82	  actor: Actor,
83	  input: DeleteWebhookInput,
84	): Promise<void> {
85	  assertOrgScope(actor, input.orgId);
86	  assertCan(actor, "webhook:manage", webhookResource(input.orgId, input.webhookId));
87	  await webhookRepo.deleteEndpoint(input.orgId, input.webhookId);
88	}
89	
90	/**
91	 * HMAC-SHA256 over the raw body, hex encoded. The receiving end recomputes
92	 * this from the same secret — it is the only thing proving the delivery came
93	 * from Taskflow, so the payload string must be signed byte-for-byte as sent.
94	 */
95	export function signPayload(secret: string, payload: string): string {
96	  return createHmac("sha256", secret).update(payload, "utf8").digest("hex");
97	}
98	
99	/**
100	 * Fans domain events out into the delivery table. Each org's endpoints
101	 * declare which event types they want, so an endpoint only ever receives what
102	 * it subscribed to; the job drains the rows afterwards.
103	 */
104	export function registerWebhookListeners(): Unsubscribe {
105	  const offs: Unsubscribe[] = [
106	    subscribe("webhook.delivery_requested", async (payload) => {
107	      await enqueueForOrg(
108	        payload.orgId,
109	        payload.eventType,
110	        JSON.stringify(payload.payload),
111	      );
112	    }),
113	    subscribe("issue.created", async (payload) => {
114	      await enqueueForOrg(payload.orgId, "issue.created", JSON.stringify(payload));
115	    }),
116	    subscribe("issue.status_changed", async (payload) => {
117	      await enqueueForOrg(
118	        payload.orgId,
119	        "issue.status_changed",
120	        JSON.stringify(payload),
121	      );
122	    }),
123	    subscribe("comment.created", async (payload) => {
124	      await enqueueForOrg(
125	        payload.orgId,
126	        "comment.created",
127	        JSON.stringify(payload),
128	      );
129	    }),
130	    subscribe("billing.plan_changed", async (payload) => {
131	      await enqueueForOrg(
132	        payload.orgId,
133	        "billing.plan_changed",
134	        JSON.stringify(payload),
135	      );
136	    }),
