"use server";

/**
 * Switches an endpoint on or off.
 *
 * Owner D. Unlike creation this is not flag- or quota-gated — a switched-off
 * endpoint still counts toward the plan's quota (see webhook-service), so
 * toggling never needs to re-check the limit.
 *
 * Must call (do not reimplement): updateWebhookSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { updateWebhookSchema, type UpdateWebhookInput } from "@/schemas/webhook";
import { updateWebhook } from "@/server/services/webhook-service";
import type { WebhookEndpointRow } from "@/server/db/schema/webhooks";
import type { ActionResult } from "@/types/api";

const run = withAction<typeof updateWebhookSchema, WebhookEndpointRow>(
  updateWebhookSchema,
  async (raw, actor) => {
    const input = raw as UpdateWebhookInput;

    const allowed = can(actor, "webhook:manage", {
      kind: "webhook",
      orgId: input.orgId,
      webhookId: input.webhookId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("webhook:manage");
    }

    const endpoint = await updateWebhook(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.hours);
    return endpoint;
  },
  { revalidate: ["webhooks"], cacheProfile: "hours" },
);

export async function toggleWebhookAction(
  raw: unknown,
): Promise<ActionResult<WebhookEndpointRow>> {
  return run(raw);
}

